BEGIN;
-- Restore profile activation after the least-privilege table-write removal.
-- The dedicated owner is not a login role and is never granted to another role.
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'academy_activation_writer') then
    raise exception 'activation writer role already exists; inspect collision before migration'
      using errcode = '55000';
  end if;
  create role academy_activation_writer
    nologin noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls
    password null;
end
$$;

alter role academy_activation_writer
  nologin noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls;

grant usage on schema academy to academy_activation_writer;
grant select, insert, update on academy.service_activation
  to academy_activation_writer;

-- Academy authorization tables are default-deny under RLS. Restrict this
-- writer policy to the dedicated function-owner role; runtime keeps no ACL.
create policy academy_service_activation_sync_writer
  on academy.service_activation
  for all
  to academy_activation_writer
  using (true)
  with check (true);

alter function academy.sync_service_activation(uuid, text, integer)
  security definer
  set search_path = pg_catalog, academy;
alter function academy.sync_service_activation(uuid, text, integer)
  owner to academy_activation_writer;

revoke all on function academy.sync_service_activation(uuid, text, integer)
  from public, anon, authenticated, service_role,
    academy_entitlement_operator, academy_staff_admin;
grant execute on function academy.sync_service_activation(uuid, text, integer)
  to academy_runtime;

SET LOCAL statement_timeout='5s';
SET LOCAL ROLE academy_runtime;
DO $test$
DECLARE account_id uuid; actual_revision integer; denied boolean := false;
BEGIN
account_id := academy.commit_identity_profile_activation('https://supabase.cyberskills.co.th/auth/v1','f9a0b7a5-8ea4-4489-8b65-bb019f2a794c','activation-fixture@example.invalid','active',1);
BEGIN
 PERFORM academy.sync_service_activation(account_id,'suspended',1);
 RAISE EXCEPTION 'equal revision conflict unexpectedly accepted';
EXCEPTION WHEN check_violation THEN NULL;
END;
PERFORM academy.sync_service_activation(account_id,'suspended',2);
PERFORM academy.sync_service_activation(account_id,'active',1);
SELECT revision INTO actual_revision FROM academy.service_activation WHERE user_id=account_id;
IF actual_revision <> 2 THEN RAISE EXCEPTION 'stale revision regressed'; END IF;
BEGIN
 UPDATE academy.service_activation SET status='active' WHERE user_id=account_id;
EXCEPTION WHEN insufficient_privilege THEN denied := true;
END;
IF NOT denied THEN RAISE EXCEPTION 'direct runtime write accepted'; END IF;
IF has_table_privilege(current_user,'academy.course_entitlement','INSERT') OR has_table_privilege(current_user,'academy.staff_role_assignment','INSERT') THEN RAISE EXCEPTION 'privilege expansion'; END IF;
RAISE NOTICE 'PASS runtime activation, equal revision conflict, newer revision, stale ignored, direct write denied, entitlement and staff denied';
END $test$;
RESET ROLE;
SELECT rolcanlogin,rolsuper,rolbypassrls FROM pg_roles WHERE rolname='academy_activation_writer';
SELECT has_function_privilege('service_role','academy.sync_service_activation(uuid,text,integer)','EXECUTE') AS shared_execute,has_table_privilege('academy_activation_writer','academy.service_activation','DELETE') AS writer_delete;
ROLLBACK;
